import { useMemo } from 'react';

import { useLastDataRefresh } from 'contexts';
import {
  type CountryExportData,
  useGetCountriesExportQuery,
} from 'redux/api/bff';

export const usePowerBookCountryData = (countryCode: string | undefined) => {
  const { lastDataRefreshKpisDateMonthYear } = useLastDataRefresh();
  const dt_end = lastDataRefreshKpisDateMonthYear?.power ?? '';
  const skip = !dt_end || !countryCode;

  const {
    data: response,
    isLoading,
    isFetching,
    error: queryError,
  } = useGetCountriesExportQuery(
    { countries: [countryCode ?? ''], dt_end, periods: ['QTD', 'YTD'] },
    { skip },
  );

  const qtdData: CountryExportData | undefined = useMemo(() => {
    if (!response || !countryCode) return undefined;
    return response.QTD?.[countryCode];
  }, [response, countryCode]);

  const ytdData: CountryExportData | undefined = useMemo(() => {
    if (!response || !countryCode) return undefined;
    return response.YTD?.[countryCode];
  }, [response, countryCode]);

  return {
    qtdData,
    ytdData,
    isLoadingCountryData: !skip && (isLoading || isFetching),
    error: queryError ? new Error('Failed to load country data') : null,
  };
};
